sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director ?birthDate WHERE {
  VALUES ?film { dbr:La_bella_Antonia,_prima_monica_e_poi_dimonia dbr:The_Commune }

  { ?film dbp:director ?director } UNION { ?film dbo:director ?director }

  OPTIONAL { 
    { ?director dbp:birthDate ?birthDate } UNION { ?director dbo:birthDate ?birthDate }
  }
}
LIMIT 100

